use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut idx = -1
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    idx = i as int
                }
                i += 1
            }
            if idx >= 0 {
                keys.remove(idx as usize)
                vals.remove(idx as usize)
            }
            keys.push(k)
            vals.push(v)
            if keys.len() as int > cap {
                println("evict ${keys[0]}")
                keys.remove(0)
                vals.remove(0)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut idx = -1
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    idx = i as int
                }
                i += 1
            }
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx as usize]
                keys.remove(idx as usize)
                vals.remove(idx as usize)
                keys.push(k)
                vals.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = keys.len()
                while i > 0 {
                    i -= 1
                    if out != "" {
                        out = out + " "
                    }
                    out = out + "${keys[i]}"
                }
                println(out)
            }
        }
    }
}

